sys_script_include.script:
var LicenseRenewalAnalyzer = Class.create();

LicenseRenewalAnalyzer.prototype = {

    initialize: function() {},

    analyzeLicense: function(assignmentId) {

        var result = {
            daysSinceLastUse: 0,
            usageScore: 0,
            costScore: 0,
            renewalScore: 0,
            recommendation: '',
            potentialSaving: 0
        };

        var assignment = new GlideRecord(
            'x_1904737_smart_0_license_assignment'
        );

        if (!assignment.get(assignmentId)) {
            return result;
        }

        // Calculate days since last usage
        var lastUsed = assignment.getValue('last_used_date');

        if (lastUsed) {

            var today = new GlideDateTime();
            var lastUsedDate = new GlideDateTime(lastUsed);

            var difference = GlideDateTime.subtract(
                lastUsedDate,
                today
            );

            result.daysSinceLastUse =
                Math.floor(difference.getNumericValue() / 86400000);
        }


        // Calculate Usage Score
        var usage30 = parseInt(
            assignment.getValue('usage_count_30_days'),
            10
        ) || 0;

        var usage90 = parseInt(
            assignment.getValue('usage_count_90_days'),
            10
        ) || 0;


        if (usage90 == 0) {

            result.usageScore = 60;

        } else if (usage30 == 0) {

            result.usageScore = 50;

        } else if (usage30 < 5) {

            result.usageScore = 30;

        } else {

            result.usageScore = 0;

        }


        // Get License
        var license = new GlideRecord(
            'x_1904737_smart_0_software_license'
        );

        if (!license.get(
                assignment.getValue('license')
            )) {
            return result;
        }


        // Calculate Cost Score
        var cost = parseFloat(
            license.getValue('license_cost')
        ) || 0;


        if (cost >= 50000) {

            result.costScore = 30;

        } else if (cost >= 20000) {

            result.costScore = 20;

        } else {

            result.costScore = 10;

        }


        // Final Renewal Score
        result.renewalScore =
            result.usageScore +
            result.costScore;


        // Recommendation
        if (result.renewalScore >= 70) {

            result.recommendation = 'do_not_renew';
            result.potentialSaving = cost;

        } else if (result.renewalScore >= 40) {

            result.recommendation = 'review';

        } else {

            result.recommendation = 'renew';

        }


        return result;
    },

    type: 'LicenseRenewalAnalyzer'
};
